"""Draw the flat lead illustrations for the Harbor Ledger seed stories into ./art (SVG, no dependencies)."""
import os, math, random
os.makedirs("art", exist_ok=True)
W, H = 1600, 1000
def svg(name, bg, body):
    open(f"art/{name}.svg", "w").write(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}">'
        f'<defs><linearGradient id="s" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="{bg[0]}"/><stop offset="1" stop-color="{bg[1]}"/></linearGradient></defs>'
        f'<rect width="{W}" height="{H}" fill="url(#s)"/>{body}</svg>')
def waves(y, color, n=5, amp=14, gap=34, op=1):
    out = ""
    for i in range(n):
        yy = y + i * gap; d = f"M0 {yy}"
        for x in range(0, W + 100, 100): d += f" q50 {-amp if (x//100)%2==0 else amp} 100 0"
        out += f'<path d="{d}" fill="none" stroke="{color}" stroke-width="6" stroke-linecap="round" opacity="{op - i*0.12:.2f}"/>'
    return out
def sea(y, c1, c2): return f'<rect y="{y}" width="{W}" height="{H-y}" fill="{c1}"/>' + waves(y + 40, c2)
def rect(x, y, w, h, c, r=0): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}"/>'
def circ(x, y, r, c, op=1): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{c}" opacity="{op}"/>'
def poly(pts, c): return f'<polygon points="{" ".join(f"{a},{b}" for a,b in pts)}" fill="{c}"/>'
def skyline(y, c, seed=1, count=16):
    random.seed(seed); x = 0; out = ""
    while x < W:
        w = random.randint(70, 150); h = random.randint(80, 300); out += rect(x, y - h, w - 8, h, c)
        for wy in range(y - h + 24, y - 20, 40):
            for wx in range(x + 16, x + w - 30, 30): out += rect(wx, wy, 12, 18, "#ffffff", 2).replace('fill="#ffffff"', 'fill="#ffffff" opacity=".25"')
        x += w
    return out
def boat(x, y, s, hull, cab):
    return (poly([(x, y), (x + 260*s, y), (x + 220*s, y + 70*s), (x + 30*s, y + 70*s)], hull) + rect(x + 70*s, y - 70*s, 110*s, 70*s, cab, 6) +
            rect(x + 90*s, y - 54*s, 26*s, 22*s, "#dbe7ef", 3) + rect(x + 130*s, y - 54*s, 26*s, 22*s, "#dbe7ef", 3) + rect(x + 150*s, y - 120*s, 10*s, 50*s, cab))
