A["chart"] = (("#fbf7ef", "#f1eadc"), "".join(f'<line x1="200" y1="{y}" x2="1420" y2="{y}" stroke="#d8cdb8" stroke-width="3"/>' for y in range(240, 820, 116)) + '<polyline points="200,760 400,720 600,690 800,610 1000,540 1200,420 1420,300" fill="none" stroke="#b23a1d" stroke-width="16" stroke-linejoin="round" stroke-linecap="round"/>' + '<polyline points="200,770 400,760 600,750 800,742 1000,730 1200,724 1420,714" fill="none" stroke="#8a5a12" stroke-width="16" stroke-linejoin="round" stroke-linecap="round"/>' + circ(1420, 300, 22, "#b23a1d") + circ(1420, 714, 22, "#8a5a12") + '<text x="1300" y="260" font-family="sans-serif" font-weight="700" font-size="44" fill="#b23a1d">Rent +11%</text><text x="1290" y="690" font-family="sans-serif" font-weight="700" font-size="44" fill="#8a5a12">Wages +3%</text>')
A["market"] = (("#f4ead7", "#efe0c4"), rect(260, 300, 1080, 560, "#7a4a24") + rect(240, 260, 1120, 70, "#5a3418") + '<text x="800" y="312" text-anchor="middle" font-family="Georgia,serif" font-size="52" fill="#f4ead7" letter-spacing="8">BRANNIGAN\'S HARDWARE</text>' + "".join(f'<path d="M{260+i*120} 330h120v60a60 60 0 0 1-120 0z" fill="{"#b23a1d" if i%2 else "#f4ead7"}"/>' for i in range(9)) + rect(340, 470, 380, 300, "#cfe3ea", 6) + rect(880, 470, 380, 390, "#3a2410", 6) + rect(380, 600, 300, 12, "#7a4a24") + "".join(rect(400 + i*60, 540, 30, 60, c, 4) for i, c in enumerate(["#c0392b", "#1f4e79", "#e3a93a", "#2f6f4f", "#6b3fa0"])) + rect(940, 530, 260, 160, "#f4ead7", 6) + '<text x="1070" y="630" text-anchor="middle" font-family="sans-serif" font-weight="700" font-size="48" fill="#b23a1d">CLOSING</text>')
A["school"] = (("#e8e1f5", "#f6f2fb"), circ(1350, 180, 80, "#f5c04a") + rect(380, 380, 840, 420, "#a0522d") + poly([(340, 390), (800, 200), (1260, 390)], "#6b3fa0") + rect(740, 260, 120, 120, "#f6f2fb", 60) + f'<line x1="800" y1="320" x2="800" y2="285" stroke="#3a2a12" stroke-width="6"/><line x1="800" y1="320" x2="830" y2="320" stroke="#3a2a12" stroke-width="6"/>' + "".join(rect(430 + i*150, 450, 90, 110, "#f6e7a6", 4) for i in range(6) if i != 2 and i != 3) + rect(720, 600, 160, 200, "#5a2d16", 4) + rect(0, 800, W, 200, "#7fb069"))
A["library"] = (("#efe6d6", "#f8f3ea"), "".join(rect(240, 260 + r*170, 1120, 16, "#6b4f35") for r in range(4)) + "".join(rect(260 + i*44 + (i//6)*20, 260 + r*170 - (110 + (i*37 + r*13) % 40), 36, 110 + (i*37 + r*13) % 40, ["#6b3fa0", "#1f4e79", "#b23a1d", "#e3a93a", "#2f6f4f", "#a8326e"][(i + r) % 6], 3) for r in range(1, 4) for i in range(22)) + rect(0, 860, W, 140, "#c9b28f"))
