A["lights"] = (("#14123a", "#3a2a6b"), "".join(circ(100 + (i*137) % 1400, 60 + (i*71) % 300, 3, "#fff", .6) for i in range(40)) + rect(0, 620, W, 40, "#5a3e2b") + "".join(rect(x, 660, 16, 160, "#5a3e2b") for x in range(60, W, 160)) + '<path d="M0 300 Q400 420 800 320 T1600 320" fill="none" stroke="#c9b37a" stroke-width="3"/>' + "".join(circ(x, 300 + 80*math.sin(x/510*math.pi) + 30, 24, c) for x, c in zip(range(80, 1600, 120), ["#ffcf5a", "#ff7a59", "#7ad7f0", "#c58bff", "#ffcf5a", "#ff7a59", "#7ad7f0", "#c58bff", "#ffcf5a", "#ff7a59", "#7ad7f0", "#c58bff", "#ffcf5a"])) + sea(820, "#1e1a4f", "#ffcf5a"))
